<script setup>
import { computed, defineComponent, h, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { gameDelta } from './mobile.js';
import { MAPS, MODES, WEAPONS } from './config.js';
import brandLogo from '../assets/branding/anka-logo-transparent.webp';

const props = defineProps({ state: { type: Object, default: () => ({}) }, networkStatus: { type: Object, default: null }, rotated: Boolean, inputVersion: Number, mobile: Boolean });
const emit = defineEmits(['start','preview','pause','resume','menu','retry','weapon','ability','mute','quality','host','join','disconnect','touchMove','touchLook','fire','aim','fullscreen']);
const s = computed(() => props.state || {});
const phase = computed(() => s.value.phase || 'menu');
const inMission = computed(() => ['playing','paused','victory','defeat'].includes(phase.value));
const selectedMap = ref(typeof s.value.map === 'string' ? s.value.map : 'desert');
const selectedMode = ref(s.value.mode || 'story');
const selectedCharacter = ref(s.value.character || 'male');
const muted = ref(!!s.value.muted);
const quality = ref(s.value.quality || 'medium');
const settingsOpen = ref(false);
const helpOpen = ref(false);
const networkOpen = ref(false);
const joinCode = ref('');
const joinError = ref('');
const stick = ref({ x: 0, y: 0 });
const stickRadius=ref(36),weaponsOpen=ref(false),firing=ref(false);
const activeMap = computed(() => MAPS.find(map => map.id === selectedMap.value) || MAPS[0]);
const activeMode = computed(() => MODES.find(mode => mode.id === selectedMode.value) || MODES[0]);
const activeWeapon = computed(() => s.value.weaponInfo || WEAPONS[Number(s.value.weapon) || 0] || WEAPONS[0]);
const hpRatio = computed(() => Math.max(0, Math.min(1, (Number(s.value.hp) || 0) / (Number(s.value.maxHp) || 120))));
const reloadRatio = computed(() => Math.max(0, Math.min(1, Number(s.value.reloading) || 0)));
const aim = computed(() => ({ left: `${Math.max(0, Math.min(100, Number(s.value.aimX ?? 50)))}%`, top: `${Math.max(0, Math.min(100, Number(s.value.aimY ?? 50)))}%` }));
const net = computed(() => props.networkStatus || (s.value.network && typeof s.value.network === 'object' ? s.value.network : { state: s.value.network || 'offline' }));
const roomCode = computed(() => net.value.code || (typeof s.value.room === 'object' ? s.value.room?.code : s.value.room) || '');
const peerCount = computed(() => Number(net.value.peers ?? (Array.isArray(s.value.peers) ? s.value.peers.length : s.value.peers)) || (roomCode.value ? 1 : 0));
const netBusy = computed(() => net.value.state === 'joining' || (net.value.state === 'hosting' && !roomCode.value));
const netError = computed(() => String(net.value.error?.message || net.value.error || ''));
const netLabel = computed(() => ({ offline:'本地作战', idle:'尚未连接', hosting:roomCode.value ? '等待队员加入' : '正在创建房间', joining:'正在建立连接', connected:'小队已连接', disconnected:'连接已断开', error:'联机失败', closed:'已离开房间' }[net.value.state] || '本地作战'));
const objective = computed(() => s.value.mode==='versus'?'三分钟对战 · 争夺击杀':typeof s.value.goal === 'string' ? s.value.goal : '清除区域内的机器军团');
const objectiveRatio = computed(() => Number(s.value.goal) > 0 ? Math.max(0, Math.min(1, 1 - (Number(s.value.remaining) || 0) / Number(s.value.goal))) : 0);
const partner = computed(() => s.value.partner || (Array.isArray(s.value.peers) ? s.value.peers.find(item => item && typeof item === 'object' && !item.local) : null));
const partnerRatio = computed(() => partner.value?.hp != null ? Math.max(0, Math.min(1, Number(partner.value.hp) / (Number(partner.value.maxHp) || 120))) : 1);
const partnerVisible = computed(() => s.value.mode === 'coop' || peerCount.value > 1 || !!partner.value);
const bossRatio = computed(() => Math.max(0, Math.min(1, (Number(s.value.boss?.hp) || 0) / (Number(s.value.boss?.max ?? s.value.boss?.maxHp) || 1))));
const clock = seconds => { const n = Math.max(0, Math.floor(Number(seconds) || 0)); return `${String(Math.floor(n / 60)).padStart(2,'0')}:${String(n % 60).padStart(2,'0')}`; };
const number = value => Math.max(0, Math.floor(Number(value) || 0)).toLocaleString('en-US');
const characterName = value => value === 'female' ? '小葵' : '小杰';
const resultTitle=computed(()=>s.value.duel?.aiType==='online'?(s.value.duel.result==='draw'?'双方平局':s.value.duel.result==='win'?'对战胜利':'对战失利'):s.value.duel?(s.value.duel.result==='draw'?'双方平局':s.value.duel.result==='win'?'蓝方胜利':'红方获胜'):(phase.value==='victory'?'任务完成':'暂别前线'));
const resultDescription=computed(()=>s.value.duel?`最终比分 ${s.value.duel.playerKills} : ${s.value.duel.botKills} · ${s.value.duel.playerKills>=s.value.duel.target||s.value.duel.botKills>=s.value.duel.target?'率先达到目标分数':'比赛时间结束'}`:(phase.value==='victory'?'据点已夺回。干得漂亮，先锋。':'重整装备，下一次突击会更出色。'));


watch(() => s.value.map, value => { if (typeof value === 'string' && MAPS.some(map => map.id === value)) selectedMap.value = value; });
watch(() => s.value.mode, value => { if (MODES.some(mode => mode.id === value)) selectedMode.value = value; });
watch(() => s.value.character, value => { if (['male','female'].includes(value)) selectedCharacter.value = value; });
watch(() => s.value.muted, value => { if (typeof value === 'boolean') muted.value = value; });
watch([selectedMap, selectedCharacter], () => emit('preview', { map: selectedMap.value, character: selectedCharacter.value }));
watch(phase, value => { settingsOpen.value = false; helpOpen.value = false; if (value !== 'playing'){releaseTouch();weaponsOpen.value=false;} });
watch(() => props.rotated, releaseTouch);
watch(() => props.inputVersion, releaseTouch);
watch(() => Number(s.value.hp)<=0, dead=>{if(dead)releaseTouch();});
function selectWeapon(index){emit('weapon',index);weaponsOpen.value=false;}
function start() { emit('start', { map: selectedMap.value, mode: selectedMode.value, character: selectedCharacter.value }); }
function toggleMute() { muted.value = !muted.value; emit('mute', muted.value); }
function setQuality(value) { quality.value = value; emit('quality', value); }
function host() { selectedMode.value = 'versus'; emit('host', { mode: selectedMode.value, map: selectedMap.value, character: selectedCharacter.value }); }
function join() { const code = joinCode.value.trim().toUpperCase().replace(/^ANKA-/, ''); if (!/^[A-Z0-9]{6}$/.test(code)) { joinError.value = '请输入六位房间码'; return; } joinError.value = ''; emit('join', { code, character: selectedCharacter.value }); }
function selectMap(id) { selectedMap.value = id; }
function ability(name) { emit('ability', name); }

let movePointer = null;
let moveCenter = { x: 0, y: 0 };
let lookPointer = null;
let lookPosition = { x: 0, y: 0 };
let firePointer = null;
let keyboardFiring = false;
let firePosition={x:0,y:0};
function moveStart(event) { if (movePointer !== null||phase.value!=='playing') return; movePointer = event.pointerId; const rect = event.currentTarget.getBoundingClientRect(); moveCenter = { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 }; stickRadius.value=event.currentTarget.clientWidth*.31; event.currentTarget.setPointerCapture?.(event.pointerId); moveUpdate(event); }
function moveUpdate(event) { if (event.pointerId !== movePointer) return; const delta=gameDelta({x:event.clientX-moveCenter.x,y:event.clientY-moveCenter.y},props.rotated); const radius = stickRadius.value; let x = delta.x / radius; let y = delta.y / radius; const length = Math.hypot(x,y); if (length > 1) { x /= length; y /= length; } stick.value = { x, y }; emit('touchMove', { x, y }); }
function moveEnd(event) { if (event.pointerId !== movePointer) return; movePointer = null; stick.value = { x: 0, y: 0 }; emit('touchMove', { x: 0, y: 0 }); }
function lookStart(event) { if (lookPointer !== null) return; lookPointer = event.pointerId; lookPosition = { x: event.clientX, y: event.clientY }; event.currentTarget.setPointerCapture?.(event.pointerId); }
function lookUpdate(event) { if (event.pointerId !== lookPointer) return; emit('touchLook', { x: event.clientX - lookPosition.x, y: event.clientY - lookPosition.y }); lookPosition = { x: event.clientX, y: event.clientY }; }
function lookEnd(event) { if (event.pointerId === lookPointer) lookPointer = null; }
function fireStart(event) { if (firePointer !== null) return; firePointer = event.pointerId; firing.value=true;firePosition={x:event.clientX,y:event.clientY}; event.currentTarget.setPointerCapture?.(event.pointerId); emit('fire', true); }
function fireUpdate(event){if(event.pointerId!==firePointer)return;emit('touchLook',{x:event.clientX-firePosition.x,y:event.clientY-firePosition.y});firePosition={x:event.clientX,y:event.clientY};}
function fireEnd(event) { if (event.pointerId !== firePointer) return; firePointer = null; firing.value=false;emit('fire', false); }
function fireKeyStart() { if (keyboardFiring) return; keyboardFiring = true; emit('fire', true); }
function fireKeyEnd() { if (!keyboardFiring) return; keyboardFiring = false; emit('fire', false); }
function releaseTouch() { if (movePointer !== null) emit('touchMove', { x:0, y:0 }); if (firePointer !== null || keyboardFiring) emit('fire', false); keyboardFiring = false;firing.value=false;emit('aim',false); movePointer = lookPointer = firePointer = null; stick.value = { x:0, y:0 }; }
function visibilityChanged() { if (document.hidden) releaseTouch(); }
onMounted(() => { window.addEventListener('blur', releaseTouch); document.addEventListener('visibilitychange', visibilityChanged); });
onBeforeUnmount(() => { releaseTouch(); window.removeEventListener('blur', releaseTouch); document.removeEventListener('visibilitychange', visibilityChanged); });

const icons = {
  expand:['M8 3H3v5M16 3h5v5M3 16v5h5M21 16v5h-5'],
  pause: ['M8 5v14M16 5v14'], play:['m9 5 11 7-11 7z'], close:['m6 6 12 12M18 6 6 18'],
  sound:['m11 5-6 5H2v4h3l6 5z','M15 8c3 2 3 6 0 8M18 4c6 4 6 12 0 16'], mute:['m11 5-6 5H2v4h3l6 5z','m16 9 6 6M22 9l-6 6'],
  settings:['M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z','M15.5 12a3.5 3.5 0 1 1-7 0 3.5 3.5 0 0 1 7 0'],
  arrow:['M3 12h17m-6-6 6 6-6 6'], reload:['M20 8a8 8 0 1 0 0 8M20 3v6h-6'],
  health:['M4 7h16v14H4zM8 7V3h8v4M12 10v8M8 14h8'], shield:['m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z','M12 6v11'],
  grenade:['M10 7h5l4 5-1 7-6 3-6-4 1-7z','M11 7V3h6M16 3l3 5'], jump:['M12 20V4m-6 6 6-6 6 6M5 21h14'],
  roll:['M7 18a8 8 0 1 1 12-1M4 13v7h7','m8 11 4-4 4 4-4 4z'], crouch:['M13 5a2 2 0 1 0 0-.1M7 11l5-3 5 5h4M12 9l-2 7 6 2v4M10 16H5v6'],
  target:['M12 2v4m0 12v4M2 12h4m12 0h4','M18 12a6 6 0 1 1-12 0 6 6 0 0 1 12 0','M12 10v4m-2-2h4'],
  link:['m9 15 6-6M8 17l-2 2a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 7l2-2a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0'],
  trophy:['M7 3h10v8a5 5 0 0 1-10 0zM7 5H3v3a4 4 0 0 0 4 4M17 5h4v3a4 4 0 0 1-4 4M12 16v5m-5 0h10'],
  skull:['M4 11a8 8 0 1 1 16 0v5l-4 1v4H8v-4l-4-1zM8 10v3m8-3v3m-5 3h2'],
  mountain:['m2 20 7-14 5 9 3-5 5 10zM6 13h6'], tree:['m12 2-7 8h4l-5 7h6v5h4v-5h6l-5-7h4z'], snow:['M12 2v20M3.3 7l17.4 10M3.3 17 20.7 7M9 4l3 3 3-3M9 20l3-3 3 3'], city:['M3 22V9h6v13M9 22V2h7v20m0-14h5v14M11 6h3m-3 4h3m-3 4h3'],
  chevron:['m8 4 8 8-8 8'], check:['m4 12 5 5L21 5'], info:['M12 10v7m0-11v1','M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0'],
};
const Icon = defineComponent({ props: { name:String }, setup(p) { return () => h('svg', { viewBox:'0 0 24 24', fill:'none', stroke:'currentColor', 'stroke-width':1.7, 'stroke-linecap':'round', 'stroke-linejoin':'round', 'aria-hidden':'true' }, (icons[p.name] || icons.target).map(d => h('path', { d }))); } });
const weaponShapes = {
 rifle:['M15 16h47l7 4h22v9H67l-6 5H40l-3 11H26l3-16H14l-7 8H1V17h14zm38 18 12 1-4 12H49z','M91 22h24v5H91M44 10h23v5H44'],
 sniper:['M8 22h64l10 3h35v4H79l-12 5H39l-5 12H23l2-16H12l-7 8H0V24zm45 12 12 1-3 11H51z','M43 12h29v7H43M58 18v5M112 20v13M90 29l7 15m-7-15-6 15'],
 shotgun:['M2 23h68l8 4h35v8H75l-8 5H41l-4 9H26l2-15H15L5 42H0V27z','M70 17h44v7H70M48 40h18M40 18h25'],
 smg:['M12 17h49l10 5h27v10H60l-3 5H41l-3 12H26l3-17H12L4 39H0V19zm44 20 10 2-4 15H51z','M98 24h17v6H98M40 10h21v6H40'],
 rocket:['M6 15h89l16 6v15l-16 6H6L0 36V21zm30 27h12l-4 11H32z','M94 15v27M13 15v27M56 5h17v9M63 5v10'],
 grenadeLauncher:['M4 20h61l14 4h31v10H77l-7 5H58l-5 10H40l2-12H25l-5 11H8l5-17H4z','M38 28a15 15 0 1 0 30 0 15 15 0 0 0-30 0M110 21v16M48 9h20v8'],
 energy:['M4 21h21l11-9h37l12 9h25v15H84L72 45H43l-6-10H24l-6 13H5l6-15H4z','M49 20h19v17H49M88 24h28v8H88M4 18v18'],
};
const WeaponGlyph = defineComponent({ props:{ type:String }, setup(p) { return () => h('svg', { viewBox:'0 0 120 58', fill:'currentColor', 'aria-hidden':'true' }, (weaponShapes[p.type] || weaponShapes.rifle).map((d,i) => h('path', {d, ...(i ? {fill:'none',stroke:'currentColor','stroke-width':3,'stroke-linecap':'round','stroke-linejoin':'round'} : {})}))); } });
const mapIcon = id => ({ desert:'mountain', jungle:'tree', snow:'snow', city:'city' }[id] || 'mountain');
</script>

<template>
  <div class="game-ui" :class="[`phase-${phase}`, { 'low-health':hpRatio < .28 && phase === 'playing' }]" @pointerdown.stop @pointerup.stop>
    <svg class="ui-sprite" width="0" height="0" aria-hidden="true"><defs><linearGradient id="anka-gold"><stop stop-color="#ffdc8f"/><stop offset="1" stop-color="#ed9c4a"/></linearGradient></defs></svg>

    <section v-if="phase === 'loading'" class="loading-screen" aria-label="正在加载游戏" role="status">
      <div class="loading-emblem"><img :src="brandLogo" alt="ANKA 双人突击标志" width="100" height="100" /></div>
      <p class="eyebrow">ANKA / TACTICAL OPERATIONS</p><h1>前哨集结中</h1>
      <p class="loading-message">{{ s.message || '正在准备角色与战场资源…' }}</p>
      <div class="loading-track"><i :style="{width:`${Math.round((Number(s.loading)||0)*100)}%`}"/></div>
      <div class="loading-meta"><span>建立作战环境</span><b>{{ Math.round((Number(s.loading)||0)*100) }}<small>%</small></b></div>
    </section>

    <section v-show="phase === 'menu'" class="menu-screen" aria-label="任务部署菜单">
      <div class="menu-shade"/>
      <header class="menu-header"><div class="brand"><img class="brand-mark" :src="brandLogo" alt="ANKA 双人突击标志" width="64" height="64" decoding="async" /><span>ANKA<span class="brand-sub">FRONTLINE SQUAD</span></span></div><div class="top-status"><span class="status-light"/>前线通讯正常<span class="build-label">V1.2 / FIELD BUILD</span></div><div id="menu-toolbar" class="menu-tools quick-toolbar" role="group" aria-label="游戏快捷设置"><button class="icon-button" type="button" :aria-label="muted?'开启声音':'关闭声音'" :title="muted?'开启声音':'关闭声音'" @click="toggleMute"><Icon :name="muted?'mute':'sound'"/></button><button class="icon-button" type="button" aria-label="画面设置" title="画面设置" :aria-expanded="settingsOpen" @click="settingsOpen=!settingsOpen"><Icon name="settings"/></button><div v-if="settingsOpen && phase==='menu'" class="settings-popover interactive"><div><strong>战场设置</strong><button class="icon-button" type="button" aria-label="关闭设置" @click="settingsOpen=false"><Icon name="close"/></button></div><p>画面质量</p><div class="quality-buttons"><button v-for="item in [{id:'low',name:'流畅'},{id:'medium',name:'均衡'},{id:'high',name:'精致'}]" :key="item.id" type="button" :class="{selected:quality===item.id}" :aria-pressed="quality===item.id" @click="setQuality(item.id)">{{item.name}}</button></div></div></div></header>
      <div class="menu-hero"><p class="eyebrow"><span/>OPERATION 001 — DUSTFALL</p><h1>前哨<span>突击</span><small>DESERT STRIKE</small></h1><p>集结你的搭档，夺回失守的边境。</p></div>
      <div class="character-callout"><span class="callout-line"/><span>{{ selectedCharacter==='female'?'02 / RECON SPECIALIST':'01 / ASSAULT SPECIALIST' }}<b>{{ characterName(selectedCharacter) }} <em>{{ selectedCharacter==='female'?'灵巧先锋':'突击先锋' }}</em></b></span></div>
      <div class="menu-columns">
        <div class="deployment-panel map-panel">
          <div class="section-label"><span>01</span><h2>选择战场</h2><small>THEATER OF OPERATIONS</small></div>
          <div class="map-grid"><button v-for="(map,index) in MAPS" :key="map.id" type="button" class="map-option" :class="{selected:selectedMap===map.id}" :style="{'--map-color':map.color}" :aria-label="`选择地图：${map.name}`" :aria-pressed="selectedMap===map.id" @click="selectMap(map.id)"><span class="map-number">0{{index+1}}</span><Icon :name="mapIcon(map.id)"/><span class="map-copy"><strong>{{map.name}}</strong><small>{{map.english}}</small></span><span v-if="selectedMap===map.id" class="selected-tick"><Icon name="check"/></span></button></div>
          <div class="section-label mode-label"><span>02</span><h2>作战模式</h2></div>
          <div class="mode-grid"><button v-for="mode in MODES" :key="mode.id" type="button" :class="{selected:selectedMode===mode.id}" :aria-label="`选择模式：${mode.name}`" :aria-pressed="selectedMode===mode.id" @click="selectedMode=mode.id"><span>{{mode.icon}}</span><strong>{{mode.name}}</strong></button></div>
          <p class="mode-description">{{activeMode.description}}</p>
        </div>
        <div class="deployment-panel launch-panel">
          <div class="section-label"><span>03</span><h2>选择先锋</h2><small>SELECT OPERATIVE</small></div>
          <div class="character-options"><button v-for="character in ['male','female']" :key="character" type="button" class="character-option" :class="[character,{selected:selectedCharacter===character}]" :aria-label="`选择${character==='male'?'男':'女'}角色：${characterName(character)}`" :aria-pressed="selectedCharacter===character" @click="selectedCharacter=character"><span class="operative-symbol">{{character==='male'?'J':'K'}}</span><span><strong>{{characterName(character)}}</strong><small>{{character==='male'?'ASSAULT / 突击':'RECON / 侦察'}}</small></span><Icon v-if="selectedCharacter===character" name="check"/></button></div>
          <div class="mission-brief"><span class="mini-label">MISSION BRIEF / 作战简报</span><h3>{{activeMap.name}}<span> / {{activeMode.name}}</span></h3><p>{{selectedMode==='versus'?'蓝方由你控制，红方为人机。先得 10 分，或三分钟结束时比分领先即获胜。':activeMap.description}}</p><div><span><i/>七类武器自由切换</span><span>{{s.perspective==='first'?'第一人称':'第三人称'}} · 3D</span></div></div>
          <div class="network-lobby"><button class="secondary-button create-room" type="button" :disabled="netBusy" @click="host"><Icon name="link"/>{{netBusy?'正在创建房间…':'邀请好友 · 双人对战'}}</button><p v-if="netError" class="network-error" role="alert">{{netError}}</p><p class="network-note">创建房间后分享二维码或链接 · 好友免注册加入</p></div>
          <button class="launch-button" type="button" :aria-label="selectedMode==='versus'&&!roomCode?'开始人机对战':'开始任务'" :disabled="netBusy || (!!roomCode && net.isHost===false)" @click="start"><span><small>{{roomCode?'SQUAD DEPLOYMENT':'READY TO DEPLOY'}}</small><strong>{{roomCode?(net.isHost===false?'等待房主部署':'部署小队'):(selectedMode==='versus'?'开始对战':'开始任务')}}</strong></span><Icon name="arrow"/></button>
          <div class="launch-foot"><span class="status-light"/>{{roomCode?`${peerCount} 名先锋已就位`:'装备就绪 · 等待出发'}}<span>ENTER THE FRONTLINE</span></div>
        </div>
      </div>
      <footer class="menu-footer"><span>ANKA DEFENSE FORCE <b> / </b> 边境守卫计划</span><span>保持移动。寻找掩体。与搭档一起赢。</span><span>24° 32′ N <b>—</b> 46° 38′ E</span></footer>
    </section>

    <div v-show="inMission" class="battle-hud" :class="{'hud-dimmed':phase!=='playing'}" aria-label="战斗状态">
      <div class="damage-vignette"/>
      <div class="player-stack"><div class="player-panel"><div class="avatar" :class="s.character==='female'?'female':'male'"><span>{{s.character==='female'?'K':'J'}}</span><i>1P</i></div><div class="player-readout"><div class="player-name"><strong>{{characterName(s.character)}}</strong><span>先锋 / {{number(s.hp)}} <small>HP</small></span></div><div class="health-track"><i :style="{width:`${hpRatio*100}%`}"/></div><div class="shield-readout"><span class="tiny-shield"><Icon name="shield"/></span><div class="shield-track"><i :style="{width:`${Math.min(100,Number(s.shield)||0)}%`}"/></div><b>{{number(s.shield)}}</b></div></div></div><div v-if="partnerVisible" class="partner-panel"><span class="partner-icon"><Icon name="link"/></span><div><strong>{{partner?.name || (peerCount>1?'在线小队':'支援搭档')}}</strong><span>{{partner?.hp!=null?`${number(partner.hp)} HP`:peerCount>1?`${peerCount} / 2 已连接`:'AI 协同作战'}}</span><div class="partner-track"><i :style="{width:`${partnerRatio*100}%`}"/></div></div></div><div class="score-readout"><span>战术积分 <b>{{number(s.score)}}</b></span><span><Icon name="skull"/>{{number(s.kills)}}</span></div></div>
